"""Per-client rate limiting at the API gateway edge."""


class TokenBucket:
    def __init__(self, capacity, refill_per_sec):
        self.capacity = float(capacity)
        self.refill_per_sec = float(refill_per_sec)
        self.tokens = float(capacity)
        self.last_ms = None

    def allow(self, now_ms):
        if self.last_ms is None:
            self.last_ms = now_ms
        elif now_ms > self.last_ms:
            elapsed = (now_ms - self.last_ms) / 1000.0
            self.tokens = min(self.capacity,
                              self.tokens + elapsed * self.refill_per_sec)
            self.last_ms = now_ms
        else:
            self.last_ms = now_ms
        if self.tokens >= 1.0:
            self.tokens -= 1.0
            return True
        return False

