        ('diagnoses', "SELECT COUNT(*) FROM diagnoses d WHERE d.service != '' AND NOT EXISTS (SELECT 1 FROM services v WHERE v.name=d.service)"),
    ]
    _bad = []
    for _label, _sql in _orphans:
        _n = _one(_sql)
